WITH pgrst_source AS ( SELECT "public"."topics"."id", "public"."topics"."slug", "public"."topics"."title", "public"."topics"."status", "public"."topics"."order_index", "public"."topics"."chapter_id", "public"."topics"."course_id", "public"."topics"."removed_at", COALESCE( "topics_memory_checks_1"."topics_memory_checks_1", '[]') AS "memory_checks", row_to_json("topics_chapter_1".*)::jsonb AS "chapter", COALESCE( "topics_cards_1"."topics_cards_1", '[]') AS "cards", COALESCE( "topics_progress_1"."topics_progress_1", '[]') AS "progress", COALESCE( "topics_exercises_1"."topics_exercises_1", '[]') AS "exercises" FROM "public"."topics" LEFT JOIN LATERAL ( SELECT json_agg("topics_memory_checks_1")::jsonb AS "topics_memory_checks_1" FROM (SELECT "exercises_1"."id", "exercises_1"."topic_id", "exercises_1"."activity_stage", "exercises_1"."removed_at", COALESCE( "exercises_questions_2"."exercises_questions_2", '[]') AS "questions" FROM "public"."exercises" AS "exercises_1" LEFT JOIN LATERAL ( SELECT json_agg("exercises_questions_2")::jsonb AS "exercises_questions_2" FROM (SELECT "questions_2"."id", "questions_2"."exercise_id", "questions_2"."group_id", "questions_2"."content", "questions_2"."explanation", "questions_2"."order_index", "questions_2"."removed_at", COALESCE( "questions_answers_3"."questions_answers_3", '[]') AS "answers", COALESCE( "questions_options_3"."questions_options_3", '[]') AS "options" FROM "public"."questions" AS "questions_2" LEFT JOIN LATERAL ( SELECT json_agg("questions_answers_3")::jsonb AS "questions_answers_3" FROM (SELECT "user_question_answers_3"."user_id", "user_question_answers_3"."selected_option_id" FROM "public"."user_question_answers" AS "user_question_answers_3" WHERE  "user_question_answers_3"."user_id" = '33333333-3333-4333-8333-333333333333' AND "user_question_answers_3"."question_id" = "questions_2"."id"   LIMIT '1000' OFFSET '0' ) AS "questions_answers_3" ) AS "questions_answers_3" ON TRUE  LEFT JOIN LATERAL ( SELECT json_agg("questions_options_3")::jsonb AS "questions_options_3" FROM (SELECT "question_options_3"."id", "question_options_3"."question_id", "question_options_3"."content", "question_options_3"."label", "question_options_3"."is_correct", "question_options_3"."order_index", "question_options_3"."removed_at" FROM "public"."question_options" AS "question_options_3" WHERE "question_options_3"."question_id" = "questions_2"."id"   LIMIT '1000' OFFSET '0' ) AS "questions_options_3" ) AS "questions_options_3" ON TRUE WHERE "questions_2"."exercise_id" = "exercises_1"."id" AND "questions_2"."course_id" = "exercises_1"."course_id"   LIMIT '1000' OFFSET '0' ) AS "exercises_questions_2" ) AS "exercises_questions_2" ON TRUE WHERE  "exercises_1"."activity_stage" = 'memory_check' AND  "exercises_1"."removed_at" IS NULL AND "exercises_1"."topic_id" = "public"."topics"."id" AND "exercises_1"."course_id" = "public"."topics"."course_id"   LIMIT '1000' OFFSET '0' ) AS "topics_memory_checks_1" ) AS "topics_memory_checks_1" ON TRUE  INNER JOIN LATERAL ( SELECT "chapters_1"."id", "chapters_1"."course_id", "chapters_1"."removed_at" FROM "public"."chapters" AS "chapters_1" WHERE "chapters_1"."id" = "public"."topics"."chapter_id" AND "chapters_1"."course_id" = "public"."topics"."course_id"   LIMIT '1000' OFFSET '0' ) AS "topics_chapter_1" ON TRUE  LEFT JOIN LATERAL ( SELECT json_agg("topics_cards_1")::jsonb AS "topics_cards_1" FROM (SELECT "cards_1"."id", "cards_1"."topic_id", "cards_1"."front_content", "cards_1"."back_content", "cards_1"."audio_url", "cards_1"."image_url", "cards_1"."order_index", "cards_1"."removed_at" FROM "public"."cards" AS "cards_1" WHERE "cards_1"."topic_id" = "public"."topics"."id"   LIMIT '1000' OFFSET '0' ) AS "topics_cards_1" ) AS "topics_cards_1" ON TRUE  LEFT JOIN LATERAL ( SELECT json_agg("topics_progress_1")::jsonb AS "topics_progress_1" FROM (SELECT "user_topic_progress_1"."topic_id", "user_topic_progress_1"."is_flashcard_completed", "user_topic_progress_1"."is_exercise_completed", "user_topic_progress_1"."is_topic_completed" FROM "public"."user_topic_progress" AS "user_topic_progress_1" WHERE "user_topic_progress_1"."topic_id" = "public"."topics"."id"   LIMIT '1000' OFFSET '0' ) AS "topics_progress_1" ) AS "topics_progress_1" ON TRUE  LEFT JOIN LATERAL ( SELECT json_agg("topics_exercises_1")::jsonb AS "topics_exercises_1" FROM (SELECT "exercises_1"."id", "exercises_1"."topic_id", "exercises_1"."course_id", "exercises_1"."title", "exercises_1"."activity_stage", "exercises_1"."part_type", "exercises_1"."order_index", "exercises_1"."removed_at", COALESCE( "exercises_questions_2"."exercises_questions_2", '[]') AS "questions", COALESCE( "exercises_groups_2"."exercises_groups_2", '[]') AS "groups" FROM "public"."exercises" AS "exercises_1" LEFT JOIN LATERAL ( SELECT json_agg("exercises_questions_2")::jsonb AS "exercises_questions_2" FROM (SELECT "questions_2"."id", "questions_2"."exercise_id", "questions_2"."group_id", "questions_2"."course_id", "questions_2"."content", "questions_2"."order_index", "questions_2"."removed_at", COALESCE( "questions_options_3"."questions_options_3", '[]') AS "options", COALESCE( "questions_answers_3"."questions_answers_3", '[]') AS "answers" FROM "public"."questions" AS "questions_2" LEFT JOIN LATERAL ( SELECT json_agg("questions_options_3")::jsonb AS "questions_options_3" FROM (SELECT "question_options_3"."id", "question_options_3"."question_id", "question_options_3"."content", "question_options_3"."label", "question_options_3"."is_correct", "question_options_3"."order_index", "question_options_3"."removed_at" FROM "public"."question_options" AS "question_options_3" WHERE "question_options_3"."question_id" = "questions_2"."id"   LIMIT '1000' OFFSET '0' ) AS "questions_options_3" ) AS "questions_options_3" ON TRUE  LEFT JOIN LATERAL ( SELECT json_agg("questions_answers_3")::jsonb AS "questions_answers_3" FROM (SELECT "user_question_answers_3"."selected_option_id" FROM "public"."user_question_answers" AS "user_question_answers_3" WHERE "user_question_answers_3"."question_id" = "questions_2"."id"   LIMIT '1000' OFFSET '0' ) AS "questions_answers_3" ) AS "questions_answers_3" ON TRUE WHERE "questions_2"."exercise_id" = "exercises_1"."id" AND "questions_2"."course_id" = "exercises_1"."course_id"   LIMIT '1000' OFFSET '0' ) AS "exercises_questions_2" ) AS "exercises_questions_2" ON TRUE  LEFT JOIN LATERAL ( SELECT json_agg("exercises_groups_2")::jsonb AS "exercises_groups_2" FROM (SELECT "question_groups_2"."id", "question_groups_2"."exercise_id", "question_groups_2"."passage_text", "question_groups_2"."audio_url", "question_groups_2"."image_url", "question_groups_2"."order_index", "question_groups_2"."removed_at", COALESCE( "question_groups_questions_3"."question_groups_questions_3", '[]') AS "questions" FROM "public"."question_groups" AS "question_groups_2" LEFT JOIN LATERAL ( SELECT json_agg("question_groups_questions_3")::jsonb AS "question_groups_questions_3" FROM (SELECT "questions_3"."id", "questions_3"."exercise_id", "questions_3"."group_id", "questions_3"."course_id", "questions_3"."content", "questions_3"."order_index", "questions_3"."removed_at", COALESCE( "questions_options_4"."questions_options_4", '[]') AS "options", COALESCE( "questions_answers_4"."questions_answers_4", '[]') AS "answers" FROM "public"."questions" AS "questions_3" LEFT JOIN LATERAL ( SELECT json_agg("questions_options_4")::jsonb AS "questions_options_4" FROM (SELECT "question_options_4"."id", "question_options_4"."question_id", "question_options_4"."content", "question_options_4"."label", "question_options_4"."is_correct", "question_options_4"."order_index", "question_options_4"."removed_at" FROM "public"."question_options" AS "question_options_4" WHERE "question_options_4"."question_id" = "questions_3"."id"   LIMIT '1000' OFFSET '0' ) AS "questions_options_4" ) AS "questions_options_4" ON TRUE  LEFT JOIN LATERAL ( SELECT json_agg("questions_answers_4")::jsonb AS "questions_answers_4" FROM (SELECT "user_question_answers_4"."selected_option_id" FROM "public"."user_question_answers" AS "user_question_answers_4" WHERE "user_question_answers_4"."question_id" = "questions_3"."id"   LIMIT '1000' OFFSET '0' ) AS "questions_answers_4" ) AS "questions_answers_4" ON TRUE WHERE "questions_3"."group_id" = "question_groups_2"."id" AND "questions_3"."exercise_id" = "question_groups_2"."exercise_id"   LIMIT '1000' OFFSET '0' ) AS "question_groups_questions_3" ) AS "question_groups_questions_3" ON TRUE WHERE "question_groups_2"."exercise_id" = "exercises_1"."id"   LIMIT '1000' OFFSET '0' ) AS "exercises_groups_2" ) AS "exercises_groups_2" ON TRUE WHERE "exercises_1"."topic_id" = "public"."topics"."id" AND "exercises_1"."course_id" = "public"."topics"."course_id"   LIMIT '1000' OFFSET '0' ) AS "topics_exercises_1" ) AS "topics_exercises_1" ON TRUE WHERE  "public"."topics"."slug" = 'lf3-perf-topic-1' AND  "public"."topics"."course_id" = 'f3010000-0000-4000-8000-000000000001' AND  "public"."topics"."status" = 'published' AND  "public"."topics"."removed_at" IS NULL   LIMIT '1000' OFFSET '0' )  SELECT null::bigint AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t;
